"""Verify an API key generated by the UI authenticates against the public v1 API."""
from pathlib import Path
from tempfile import TemporaryDirectory
import json
import socket
import sqlite3
import subprocess
import sys
import time

from playwright.sync_api import sync_playwright

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "reports" / "launch-audit-v14"))
import browser_acceptance_v14 as helper


with TemporaryDirectory(prefix="paperplane-id94-developer-api-") as temp:
    data_dir = Path(temp) / "data"
    app, base, identities = helper.start_server(data_dir)
    try:
        port = int(base.rsplit(":", 1)[1])
        for _ in range(100):
            if app.poll() is not None:
                raise RuntimeError(f"app exited with {app.returncode}")
            try:
                with socket.create_connection(("127.0.0.1", port), timeout=0.2):
                    break
            except OSError:
                time.sleep(0.15)
        email, token = identities["accounts"][0]
        database = sqlite3.connect(data_dir / "paperplane.sqlite3")
        try:
            database.execute("UPDATE users SET tier='developer' WHERE email=?", (email,))
            database.commit()
        finally:
            database.close()

        results = []
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch(channel="chrome", headless=True)
            for round_number in (1, 2):
                context = browser.new_context(viewport={"width": 1366, "height": 900})
                context.add_cookies([{"name": "paperplane_token", "value": token, "url": base, "httpOnly": True}])
                page = context.new_page()
                errors = []
                page.on("pageerror", lambda error: errors.append(str(error)))
                page.goto(base + "/settings", wait_until="domcontentloaded")
                page.wait_for_function("document.querySelector('#settings-user-email')?.textContent.includes('audit-')", timeout=10000)
                page.locator("#settings-tab-btn-api").click()
                page.locator("#settings-create-key-form").wait_for(state="visible")
                page.locator("#settings-key-name").fill(f"ID 94 browser key round {round_number}")
                with page.expect_response(lambda response: response.url.endswith("/api/developer/keys") and response.request.method == "POST") as generated:
                    page.locator("#settings-create-key-form button[type=submit]").click()
                assert generated.value.status == 200, generated.value.status
                page.locator("#settings-new-key-alert").wait_for(state="visible")
                key = page.locator("#settings-new-key-alert [data-copy-value]").first.get_attribute("data-copy-value")
                assert key and key.startswith("sk_live_"), "generated key not present in the one-time browser response"
                usage = page.evaluate("async key => {const r=await fetch('/api/v1/account/usage',{headers:{Authorization:`Bearer ${key}`}});return {status:r.status,body:await r.json()}}", key)
                assert usage["status"] == 200, usage
                assert usage["body"].get("account") or usage["body"].get("daily_limit") is not None, usage
                assert not errors, errors
                page.locator("#settings-new-key-alert").evaluate("element => { element.textContent = 'API key generated and accepted by the local API. Test secret redacted.'; }")
                page.screenshot(path=str(OUT / f"id94-developer-key-round{round_number}.png"), full_page=True)
                results.append({"round": round_number, "generation_status": generated.value.status, "key_prefix_only": key[:12], "usage_api_status": usage["status"], "usage_fields": sorted(usage["body"].keys()), "page_errors": errors})
                context.close()
            browser.close()
        result = {"workflow": "Generate API key in signed-in Developer Settings, then authenticate a public API request with the generated key", "rounds": results}
        (OUT / "browser-id94-developer-key-self-auth.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
        print(json.dumps(result, indent=2))
    finally:
        if sys.platform == "win32":
            subprocess.run(["taskkill", "/PID", str(app.pid), "/T", "/F"], capture_output=True, text=True)
        if app.poll() is None:
            app.terminate()
        app.wait(timeout=5)
        time.sleep(0.5)
